import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-thumbnail-card';
  group.position.set(-1.25, -1.1, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const INK = '#16161d';
  const PAPER = '#e8ecf2';
  const ACCENT = '#ff2a38';
  const SURFACE = '#0b0b10';

  // Card frame / backing plate (machined-metal PBR)
  const cardGeo = new THREE.BoxGeometry(1.6, 1.0, 0.05);
  const cardMat = new MeshStandardNodeMaterial();
  cardMat.colorNode = color(INK);
  cardMat.metalness = 0.5;
  cardMat.roughness = 0.55;
  cardMat.clearcoat = 0.2;
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0.08, -0.05);
  group.add(cardMesh);

  // Caption strip
  const stripGeo = new THREE.BoxGeometry(1.6, 0.22, 0.06);
  const stripMat = new MeshStandardNodeMaterial();
  stripMat.colorNode = color(SURFACE);
  stripMat.metalness = 0.4;
  stripMat.roughness = 0.6;
  const stripMesh = new THREE.Mesh(stripGeo, stripMat);
  stripMesh.position.set(0, -0.5, -0.04);
  group.add(stripMesh);

  // Accent rim light strip along top edge
  const rimGeo = new THREE.BoxGeometry(1.62, 0.02, 0.02);
  const rimMat = new MeshStandardNodeMaterial();
  rimMat.colorNode = color(ACCENT);
  rimMat.emissiveNode = color(ACCENT);
  rimMat.metalness = 0.3;
  rimMat.roughness = 0.4;
  const rimMesh = new THREE.Mesh(rimGeo, rimMat);
  rimMesh.position.set(0, 0.6, -0.02);
  group.add(rimMesh);

  // Placeholder holder for the loaded mesh (gear-a.glb)
  const meshHolder = new THREE.Group();
  meshHolder.position.set(0, 0.12, 0.05);
  group.add(meshHolder);

  let loadedMesh = null;
  try {
    const gltf = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');
    if (gltf && gltf.scene) {
      loadedMesh = gltf.scene;
      loadedMesh.scale.set(0.55, 0.55, 0.55);
      loadedMesh.position.set(0, 0, 0);
      meshHolder.add(loadedMesh);
    }
  } catch (e) {
    // silently continue without mesh if load fails
  }

  // Apply cinematic primitives
  ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
  ctx.primitives['magnetic-cursor'](group, { radius: 1.2, strength: 0.35 });

  // Interaction state
  const baseY = group.position.y;
  let hoverTl = null;

  const onHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onClick = () => {
    gsap.to(group.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
      onComplete: () => {
        if (group.userData.emit) {
          group.userData.emit('hub-features.select');
        }
      }
    });
  };

  group.userData.handlers = {
    onHoverIn,
    onHoverOut,
    onClick
  };

  // weighted-settle entrance
  group.scale.set(0.96, 0.96, 0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.5,
    ease: 'power4.out'
  }).to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.4,
    ease: 'power4.out'
  });

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (entranceTl) entranceTl.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    cardGeo.dispose();
    cardMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    rimGeo.dispose();
    rimMat.dispose();

    if (loadedMesh) {
      loadedMesh.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
  };

  return group;
}
